<script setup lang="ts">
import ConsoleDiscardChangesDialog from '~/components/console/ConsoleDiscardChangesDialog.vue'
const discard=useDiscardChanges(()=>!!busy.value||imageBusy.value)
import TenantMiniProgramUpload from '../../components/tenant/TenantMiniProgramUpload.vue'
import TenantMiniAds from '../../components/tenant/TenantMiniAds.vue'
import MaterialPicker from '../../components/console/MaterialPicker.vue'
import ImageSelectTile from '../../components/console/ImageSelectTile.vue'
import ConsoleValidatedForm from '../../components/console/ConsoleValidatedForm.vue'
import AdminConsole from '../../components/console/AdminConsole.vue'
import ConsoleSettingsActions from '../../components/console/ConsoleSettingsActions.vue'
import ConsolePageHeading from '@orangezh1/qisvc-console-ui/components/ConsolePageHeading'
import ConsoleSettingsField from '@orangezh1/qisvc-console-ui/components/ConsoleSettingsField'
import ConsoleInput from '@orangezh1/qisvc-console-ui/components/ConsoleInput'
definePageMeta({layout:'tenant',key:route=>route.path})
type Config={enabled:boolean;displayName:string;originalId:string;appId:string;subjectType:'unknown'|'personal'|'business';versionDescription:string;qrMaterialId:string|null}
type View={uploadSupported?:boolean;applicationKey:string|null;applications:{key:string;name:string}[];version:number;config:Config;hasAppSecret:boolean;hasUploadPrivateKey:boolean;domains:{available:boolean;request:string;uploadFile:string;downloadFile:string;socket:string;udp:string;business:string;message:string};paymentAppId:string;paymentEnabled:boolean;canWrite:boolean}
const auth=useApi('tenant'),tenantId=useTenantContext().tenantId.value,endpoint='/admin/tenants/'+encodeURIComponent(tenantId)+'/mini-program',toast=useToast()
const initialApplication=typeof useRoute().query.application==='string'?String(useRoute().query.application):''
const initial=await useAsyncData<View>('tenant-mini-program:'+auth.session.value?.id+':'+tenantId+':'+initialApplication,(_nuxt,{signal})=>auth.api<View>(endpoint+(initialApplication?'?applicationKey='+encodeURIComponent(initialApplication):''),'GET',undefined,{signal}))
if(initial.error.value&&!auth.session.value)await navigateTo('/admin/login',{replace:true})
const data=ref<View|null>(initial.data.value??null),applicationKey=ref(data.value?.applicationKey||''),form=ref<Config|null>(data.value?{...data.value.config}:null),baseline=ref(JSON.stringify(form.value)),appSecret=ref(''),uploadPrivateKey=ref(''),busy=ref<'save'|'refresh'|'retry'|'application'|'check'|null>(null),error=ref(initial.error.value?.message||'')
const dirty=computed(()=>JSON.stringify(form.value)!==baseline.value||!!appSecret.value||!!uploadPrivateKey.value),locked=computed(()=>!!busy.value||!data.value?.canWrite)
const mismatch=computed(()=>form.value?.subjectType!=='personal'&&!!data.value?.paymentEnabled&&!!form.value?.appId&&!!(appSecret.value||data.value?.hasAppSecret)&&data.value.paymentAppId!==form.value.appId)
const imageOpen=ref(false),imageBusy=ref(false),copying=ref(''),materialEndpoint='/admin/tenants/'+encodeURIComponent(tenantId)+'/materials/shared'
const tab=useRouteTab<string>('settings',()=>data.value?.applicationKey?['settings','ads']:['settings']),adsPanel=ref<InstanceType<typeof TenantMiniAds>|null>(null)
const refreshing=computed(()=>tab.value==='ads'?!!adsPanel.value?.refreshing:busy.value==='refresh')
function refreshPage(){if(tab.value==='ads'){void adsPanel.value?.refresh();return}void refresh()}
function selectTab(value:string|number){const next=String(value);if(!['settings','ads'].includes(next)||next===tab.value||busy.value||imageBusy.value)return;const move=()=>{tab.value=next};if(tab.value==='ads'){adsPanel.value?.requestLeave(move);return}if(dirty.value){discard.request(()=>{cancel();move()});return}move()}
const domains=[{key:'request',label:'request 合法域名',help:'用于小程序 HTTPS 接口请求。'},{key:'socket',label:'socket 合法域名',help:'仅在使用 WSS 长连接时配置。'},{key:'uploadFile',label:'uploadFile 合法域名',help:'用于上传文件到本站接口。'},{key:'downloadFile',label:'downloadFile 合法域名',help:'用于下载本站文件；对象存储或 CDN 须补充实际域名。'},{key:'udp',label:'UDP 合法域名',help:'仅在使用 UDP 通信时配置。'}] as const
async function copyDomain(key:keyof View['domains']){const value=data.value?.domains[key];if(typeof value!=='string'||!value||copying.value)return;copying.value=key;try{await navigator.clipboard.writeText(value);toast.add({title:'已复制',color:'success'})}catch{error.value='复制失败，请手动复制域名'}finally{copying.value=''}}
const controller=new AbortController();let disposed=false
function fill(value:View){data.value=value;applicationKey.value=value.applicationKey||'';form.value={...value.config};baseline.value=JSON.stringify(form.value);appSecret.value='';uploadPrivateKey.value=''}
function cancel(){if(busy.value)return;form.value=JSON.parse(baseline.value);appSecret.value='';uploadPrivateKey.value='';error.value='';discard.keep()}
async function refresh(source:'refresh'|'retry'|'application'='refresh',key=applicationKey.value){if(busy.value)return;if(dirty.value){discard.request(()=>{cancel();void refresh(source,key)});return}busy.value=source;error.value='';try{const result=await auth.api<View>(endpoint+(key?'?applicationKey='+encodeURIComponent(key):''),'GET',undefined,{signal:controller.signal});if(!disposed)fill(result)}catch(e:any){if(!disposed)error.value=e.message||'小程序配置读取失败'}finally{if(!disposed)busy.value=null}}
async function check(){if(busy.value||dirty.value||!data.value?.canWrite)return;busy.value='check';error.value='';try{const result=await auth.api<{message:string}>(endpoint+'/'+encodeURIComponent(applicationKey.value)+'/check','POST',{version:data.value.version},{signal:controller.signal});if(!disposed)toast.add({title:result.message,color:'success'})}catch(e:any){if(!disposed)error.value=e.message}finally{if(!disposed)busy.value=null}}
function chooseApplication(value:string){if(value===applicationKey.value)return;const move=()=>{void refresh('application',value)};if(tab.value==='ads')adsPanel.value?.requestLeave(move);else move()}
async function save(){if(imageBusy.value||locked.value||!dirty.value||!form.value||!data.value||!applicationKey.value)return;if(form.value.subjectType!=='personal'&&mismatch.value){error.value='小程序 AppID 与已配置的微信支付 AppID 不一致';return}busy.value='save';error.value='';try{const result=await auth.api<View>(endpoint+'/'+encodeURIComponent(applicationKey.value),'PUT',{version:data.value.version,config:{...form.value},appSecret:appSecret.value,uploadPrivateKey:uploadPrivateKey.value},{signal:controller.signal});if(!disposed){fill(result);toast.add({title:'小程序配置已保存',color:'success'})}}catch(e:any){if(!disposed)error.value=e.message||'保存失败'}finally{if(!disposed)busy.value=null}}
usePageLeaveGuard(to=>{if(!auth.session.value)return;if(!!busy.value||imageBusy.value){toast.add({title:'正在处理，请稍候再离开',color:'neutral'});return false}if(dirty.value){return discard.decide(cancel)}})
useUnsavedBeforeUnload(()=>dirty.value||!!busy.value||imageBusy.value)
onBeforeUnmount(()=>{disposed=true;controller.abort();appSecret.value='';uploadPrivateKey.value='';busy.value=null})
</script>
<template><AdminConsole :refreshing="refreshing" @refresh="refreshPage"><div class="space-y-5">
 <ConsolePageHeading title="微信小程序"><template #actions><USelect v-if="data&&data.applications.length>1" :model-value="applicationKey" :items="data.applications.map(app=>({value:app.key,label:app.name}))" aria-label="小程序所属应用" :disabled="!!busy" @update:model-value="chooseApplication"/></template></ConsolePageHeading>
 <UTabs v-if="data?.applicationKey" :model-value="tab" :items="[{label:'基础配置',value:'settings'},{label:'广告配置',value:'ads'}]" :content="false" variant="link" :ui="{trigger:'cursor-pointer'}" aria-label="小程序配置" @update:model-value="selectTab"/>
 <TenantMiniAds v-if="tab==='ads'&&data?.applicationKey" ref="adsPanel" :key="applicationKey" :endpoint="endpoint+'/'+encodeURIComponent(applicationKey)+'/ads'" @configure="selectTab('settings')"/>
 <template v-if="tab==='settings'">
 <UAlert v-if="error" color="error" :title="error"><template v-if="!data" #actions><UButton :loading="busy==='retry'" @click="refresh('retry')">重试</UButton></template></UAlert>
 <ConsoleValidatedForm v-if="form&&data?.applicationKey" class="space-y-5" @submit="save" @invalid="error=$event"><section class="surface-card mini-form space-y-6 p-5 sm:p-7"><h2 class="text-base font-semibold">小程序基础信息</h2>
  <ConsoleSettingsField label="主体类型" input-id="mini-subject"><USelect id="mini-subject" v-model="form.subjectType" :items="[{value:'unknown',label:'请选择主体类型'},{value:'personal',label:'个人主体'},{value:'business',label:'企业 / 个体工商户'}]" class="w-full" :disabled="locked"/><p class="mt-2 text-xs text-muted">按微信公众平台登记主体填写，开通资格以微信审核结果为准。个人与企业的虚拟商品均使用虚拟支付。</p></ConsoleSettingsField>
  <ConsoleSettingsField label="小程序名称" input-id="mini-name"><ConsoleInput id="mini-name" v-model="form.displayName" :maxlength="32" :disabled="locked" placeholder="请输入小程序名称"/></ConsoleSettingsField>
  <ConsoleSettingsField label="原始 ID" input-id="mini-original-id"><ConsoleInput id="mini-original-id" v-model="form.originalId" :maxlength="64" :disabled="locked" placeholder="gh_ 开头，选填"/></ConsoleSettingsField>
  <ConsoleSettingsField label="小程序码"><ImageSelectTile :src="form.qrMaterialId?'/api/v1'+materialEndpoint+'/'+form.qrMaterialId+'/content':null" label="小程序码" fit="contain" :disabled="locked||imageBusy" :removable="!!form.qrMaterialId" @select="imageOpen=true" @remove="form.qrMaterialId=null"/><p class="mt-2 text-xs text-muted">建议使用 400 × 400px 图片，从本站素材库上传或选择。移除只解除关联。</p></ConsoleSettingsField>
 </section><section class="surface-card mini-form space-y-6 p-5 sm:p-7"><h2 class="text-base font-semibold">开发者配置</h2>
  <ConsoleSettingsField label="AppID" input-id="mini-app-id"><ConsoleInput id="mini-app-id" v-model="form.appId" :maxlength="18"  :disabled="locked" autocomplete="off" placeholder="wx 开头的微信小程序 AppID"/><p v-if="data.paymentAppId" class="mt-2 text-xs text-muted">微信支付 AppID：{{data.paymentAppId}}</p><p v-if="mismatch" class="mt-2 text-xs text-error">须与已配置的微信支付 AppID 保持一致。</p></ConsoleSettingsField>
  <ConsoleSettingsField label="AppSecret" input-id="mini-app-secret"><ConsoleInput id="mini-app-secret" v-model="appSecret" type="password" autocomplete="new-password" :maxlength="32" :disabled="locked" :placeholder="data.hasAppSecret?'已保存，留空保留；填写新值可替换':'请输入 32 位 AppSecret'"/><p class="mt-2 text-xs text-muted">密钥加密保存，不回显。更换 AppID 后须重新填写对应密钥。</p></ConsoleSettingsField>
 </section><section class="surface-card mini-form space-y-6 p-5 sm:p-7"><h2 class="text-base font-semibold">服务器域名</h2><p class="text-xs text-muted">{{data.domains?.message}}</p>
  <ConsoleSettingsField v-for="domain in domains" :key="domain.key" :label="domain.label"><div class="flex min-w-0 items-center gap-3"><ConsoleInput class="min-w-0 flex-1" :model-value="data.domains?.[domain.key]||''" readonly :aria-label="domain.label"/><UButton type="button" class="min-w-20 shrink-0 justify-center whitespace-nowrap" color="neutral" variant="outline" icon="i-lucide-copy" :loading="copying===domain.key" :disabled="!!copying||!data.domains?.[domain.key]" @click="copyDomain(domain.key)">复制</UButton></div><p class="mt-2 text-xs text-muted">{{domain.help}}</p></ConsoleSettingsField>
 </section><section class="surface-card mini-form space-y-6 p-5 sm:p-7"><h2 class="text-base font-semibold">业务域名</h2><ConsoleSettingsField label="业务域名"><div class="flex min-w-0 items-center gap-3"><ConsoleInput class="min-w-0 flex-1" :model-value="data.domains?.business||''" readonly aria-label="业务域名"/><UButton type="button" class="min-w-20 shrink-0 justify-center whitespace-nowrap" color="neutral" variant="outline" icon="i-lucide-copy" :loading="copying==='business'" :disabled="!!copying||!data.domains?.business" @click="copyDomain('business')">复制</UButton></div><p class="mt-2 text-xs text-muted">用于 web-view 内嵌本站网页，仅在实际使用时配置并完成微信域名校验。</p></ConsoleSettingsField>
 </section><section class="surface-card"><div class="mini-form space-y-6 p-5 sm:p-7"><h2 class="text-base font-semibold">小程序代码上传</h2>
  <ConsoleSettingsField label="上传密钥" input-id="mini-upload-key"><UTextarea id="mini-upload-key" v-model="uploadPrivateKey" class="w-full" :rows="4" :maxlength="12000" :disabled="locked" :placeholder="data.hasUploadPrivateKey?'已保存，留空保留；填写新密钥可替换':'粘贴微信小程序代码上传密钥（PEM）'"/><p class="mt-2 text-xs text-muted">在微信公众平台的开发管理中取得，密钥加密保存。更换 AppID 后须重新设置。</p></ConsoleSettingsField>
  <ConsoleSettingsField label="版本说明" input-id="mini-description"><UTextarea id="mini-description" v-model="form.versionDescription" class="w-full" :rows="2" :maxlength="200" :disabled="locked" placeholder="本次版本的更新内容"/></ConsoleSettingsField>
  <p class="border-t border-default pt-5 text-xs text-muted">更换 AppID 后，原微信登录会话将失效。已有客户和业务记录保留。</p>
 </div></section><ConsoleSettingsActions :dirty="dirty" :busy="!!busy" :saving="busy==='save'" :can-write="data.canWrite" :save-disabled="mismatch||imageBusy" @cancel="discard.request(cancel)"><template #before><UButton v-if="data.canWrite" type="button" color="neutral" variant="outline" :loading="busy==='check'" :disabled="!!busy||dirty||!data.hasAppSecret" @click="check">验证小程序凭据</UButton></template></ConsoleSettingsActions></ConsoleValidatedForm>
 <TenantMiniProgramUpload v-if="data?.applicationKey&&data.uploadSupported!==false" :key="tenantId+applicationKey" :endpoint="endpoint+'/'+encodeURIComponent(applicationKey)" :settings-version="data.version" :can-write="data.canWrite" :dirty="dirty||!!busy" :ready="!!data.config.enabled&&!!data.hasUploadPrivateKey&&!!data.domains?.available"/>
 <p v-else-if="data?.applicationKey" class="text-xs text-muted">当前尚未提供托管小程序发行版本，渠道配置可先保存。</p><p v-else-if="data" class="py-10 text-center text-sm text-muted">请选择要配置小程序的应用。</p>
 <MaterialPicker v-if="form" v-model:open="imageOpen" portal="tenant" :endpoint="materialEndpoint" kind="image" @busy="imageBusy=$event" @select="form.qrMaterialId=$event.id"/>
 </template>
 <ConsoleDiscardChangesDialog :controller="discard"/>
</div></AdminConsole></template>
<style scoped>.mini-form{--settings-label-width:11rem;--settings-content-width:36rem}</style>
